//! One live test per documented top-level collection: each reads the
//! first item through the resource layer and decodes it through the typed
//! models.
//!
//! This file is generated by `scripts/generate_endpoint_manifest.py`.

use super::live_client;
use std::fmt::Debug;

fn check<T: Debug>(operation: &str, result: rentman_client::Result<Vec<T>>) {
    if let Err(error) = result {
        panic!("{operation} failed against the live API: {error:#}");
    }
}

#[tokio::test]
#[ignore = "calls the real Rentman API; requires RENTMAN_API_TOKEN"]
async fn get_accessory_collection() {
    check(
        "getAccessoryCollection",
        live_client().accessories().list().first(1).await,
    );
}

